1	import type { Claim, Entry, EvidenceRef, Session } from '@dailies/core';
2	import type { CommandClass } from './commands';
3	import { classifyCommand } from './commands';
4	import { collectRuns, parseOutcome, type ToolRun } from './results';
5	import { normalize, quoteMatches } from './quote';
6	
7	type Verdicted = Pick<Claim, 'verdict' | 'reason' | 'evidence'>;
8	
9	const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit']);
10	
11	function findEntry(session: Session, entryId: string): Entry | undefined {
12	  return session.entries.find((e) => e.id === entryId);
13	}
14	
15	function entryRef(entryId: string): EvidenceRef {
16	  return { type: 'entry', entryId };
17	}
18	
19	function runEvidence(run: ToolRun): EvidenceRef[] {
20	  const refs: EvidenceRef[] = [entryRef(run.callEntryId)];
21	  if (run.resultEntryId) refs.push(entryRef(run.resultEntryId));
22	  return refs;
23	}
24	
25	function unverifiable(reason: string): Verdicted {
26	  return { verdict: 'unverifiable', reason, evidence: [] };
27	}
28	
29	// Shared by tests_pass (class ['test']) and build_passes (classes ['build', 'typecheck', 'lint']):
30	// consider the last matching run before the claim's entry, then check for an edit since.
31	function lastRunVerdict(claim: Claim, session: Session, classes: CommandClass[], noRunReason: string): Verdicted {
32	  const claimEntry = findEntry(session, claim.entryId);
33	  if (!claimEntry) return unverifiable('claim entry not found in session');
34	
35	  const runs = collectRuns(session).filter((r) => classes.includes(r.cls) && r.index < claimEntry.index);
36	  if (runs.length === 0) return unverifiable(noRunReason);
37	
38	  const last = runs[runs.length - 1]!;
39	  if (last.outcome === 'fail') return { verdict: 'contradicted', reason: 'the last recorded run failed', evidence: runEvidence(last) };
40	  if (last.outcome === 'unknown') return unverifiable('the last recorded run output was not recognised');
41	
42	  const edit = session.entries.find(
43	    (e) =>
44	      e.kind === 'tool_call' &&
45	      e.index > last.index &&
46	      e.index < claimEntry.index &&
47	      e.toolName !== undefined &&
48	      EDIT_TOOLS.has(e.toolName) &&
49	      e.filePath !== undefined &&
50	      !e.filePath.endsWith('.md')
51	  );
52	  if (edit) {
53	    return {
54	      verdict: 'stale',
55	      reason: 'a source file was edited after the last passing run',
56	      evidence: [entryRef(edit.id), ...runEvidence(last)],
57	    };
58	  }
59	  return { verdict: 'verified', reason: 'the last recorded run passed with no edits after', evidence: runEvidence(last) };
60	}
61	
62	function ranCommand(claim: Claim, session: Session): Verdicted {
63	  const claimEntry = findEntry(session, claim.entryId);
64	  if (!claimEntry || !claim.subject) return unverifiable('no matching command is recorded before this message');
65	
66	  const subject = normalize(claim.subject);
67	  if (!subject) return unverifiable('no matching command is recorded before this message');
68	  const calls = session.entries.filter(
69	    (e) => e.kind === 'tool_call' && e.index < claimEntry.index && e.command && normalize(e.command).includes(subject)
70	  );
71	  if (calls.length === 0) return unverifiable('no matching command is recorded before this message');
72	
73	  const call = calls[calls.length - 1]!;
74	  const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
75	  if (!result) return unverifiable('the matching command has no recorded result');
76	
77	  const evidence = [entryRef(call.id), entryRef(result.id)];
78	  if (result.isError) return { verdict: 'contradicted', reason: 'the matching command errored', evidence };
79	  return { verdict: 'verified', reason: 'the matching command succeeded', evidence };
80	}
81	
82	function fixedError(claim: Claim, session: Session): Verdicted {
83	  const claimEntry = findEntry(session, claim.entryId);
84	  if (!claimEntry || !claim.subject) return unverifiable('no error text is recorded for this claim');
85	
86	  const subject = normalize(claim.subject);
87	  if (!subject) return unverifiable('no error text is recorded for this claim');
88	  const errorResult = session.entries.find(
89	    (e) => e.kind === 'tool_result' && e.index < claimEntry.index && normalize(e.text).includes(subject)
90	  );
91	  if (!errorResult) return unverifiable('the error text is not recorded in any tool result');
92	
93	  const errorCall = session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === errorResult.toolUseId);
94	  if (!errorCall || !errorCall.command) return unverifiable('the failing command is not recorded');
95	  const cls = classifyCommand(errorCall.command);
96	
97	  const laterCalls = session.entries.filter(
98	    (e) =>
99	      e.kind === 'tool_call' &&
100	      e.index > errorResult.index &&
101	      e.index < claimEntry.index &&
102	      e.command &&
103	      classifyCommand(e.command) === cls
104	  );
105	  if (laterCalls.length === 0) return unverifiable('no later run of the same kind is recorded before this message');
106	
107	  const lastCall = laterCalls[laterCalls.length - 1]!;
108	  const lastResult = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === lastCall.toolUseId);
109	  if (!lastResult) return unverifiable('the later run has no recorded result');
110	
111	  const outcome = parseOutcome(cls, lastResult.text, lastResult.isError ?? false);
112	  const stillPresent = normalize(lastResult.text).includes(subject);
113	  const evidence: EvidenceRef[] = [entryRef(errorResult.id), entryRef(lastCall.id), entryRef(lastResult.id)];
114	
115	  if (stillPresent || outcome === 'fail') {
116	    return { verdict: 'contradicted', reason: 'the error is still present in a later run', evidence };
117	  }
118	  if (outcome === 'unknown') return unverifiable('the later run output was not recognised');
119	  return { verdict: 'verified', reason: 'a later run no longer shows the error', evidence };
120	}
121	
122	export function verifyClaim(claim: Claim, session: Session): Claim {
123	  if (claim.kind === 'implemented') return claim;
124	
125	  const entry = findEntry(session, claim.entryId);
126	  if (!entry || !quoteMatches(claim.quote, entry.text)) {
127	    return { ...claim, verdict: 'unverifiable', reason: 'quote not found in transcript', evidence: [] };
128	  }
129	
130	  let result: Verdicted;
131	  switch (claim.kind) {
132	    case 'tests_pass':
133	      result = lastRunVerdict(claim, session, ['test'], 'no test run is recorded before this message');
134	      break;
135	    case 'build_passes':
136	      result = lastRunVerdict(claim, session, ['build', 'typecheck', 'lint'], 'no build, typecheck or lint run is recorded before this message');
137	      break;
138	    case 'ran_command':
139	      result = ranCommand(claim, session);
140	      break;
141	    case 'fixed_error':
142	      result = fixedError(claim, session);
143	      break;
144	    default:
145	      result = unverifiable('unknown claim kind');
146	  }
147	  return { ...claim, ...result };
148	}
149	
150	export function verifyClaims(claims: Claim[], sessions: Session[]): Claim[] {
151	  const byId = new Map(sessions.map((s) => [s.id, s]));
152	  return claims.map((c) => {
153	    const session = byId.get(c.sessionId);
154	    if (!session) return { ...c, verdict: 'unverifiable', reason: 'session not found', evidence: [] };
155	    return verifyClaim(c, session);
156	  });
157	}
